mapper.select:
WITH root AS ( SELECT C.CO_CD , C.ORDRS_NO , C.ORDRS_CLNT_CD , B.CLNT_NM AS ORDRS_CLNT_NM , C.CLNT_PJT , M.CODE_NM AS CLNT_PJT_NM , C.CTRT_NM , 'ROOT' AS ISROOT FROM TB_CR02M01 C LEFT JOIN TB_CM05M01 M ON M.CODE_ID = C.CLNT_PJT LEFT JOIN TB_BM02M01 B ON B.CLNT_CD = C.ORDRS_CLNT_CD WHERE 1=1
AND C.ORDRS_NO LIKE '%' || #{ordrsNo} || '%'
) , salesCd AS ( SELECT C.CO_CD , C.ORDRS_NO , C.ORDRS_CLNT_CD , C.ORDRS_CLNT_NM , C.CLNT_PJT , C.CLNT_PJT_NM , C.CTRT_NM , '' AS ISROOT , D.SALES_CD , D.EQP_NM , D.MCTYPE , M.CODE_NM AS MCTYPE_NM , D.ORDRS_SEQ FROM root C JOIN TB_CR02D02 D ON D.CO_CD = C.CO_CD AND D.ORDRS_NO = C.ORDRS_NO LEFT JOIN TB_CM05M01 M ON M.CODE_ID = D.MCTYPE WHERE D.SALES_CD IS NOT NULL
AND D.SALES_CD LIKE '%' || #{salesCd} || '%'
) , wbs as ( SELECT W.CO_CD, W.SALES_CD, MAX(W.VER_NO) AS VER_NO FROM TB_WB22M01 W JOIN salesCd S ON S.CO_CD = W.CO_CD AND S.SALES_CD = W.SALES_CD GROUP BY W.CO_CD, W.SALES_CD ) , iss AS ( SELECT S.CO_CD , S.ORDRS_NO , S.ORDRS_CLNT_CD , S.ORDRS_CLNT_NM , S.CLNT_PJT , S.CLNT_PJT_NM , S.CTRT_NM , S.ISROOT , S.SALES_CD , S.EQP_NM , S.MCTYPE , S.MCTYPE_NM , W.ISS_SJ , W.ISS_NO , CASE WHEN ((W.ISS_STS = 'ISSSTS03') OR (Q.REQ_ST = 'REQST03')) THEN 'ISSSTS03' WHEN ((W.ISS_STS = 'ISSSTS02') OR (W.REQ_NO IS NOT NULL)) THEN 'ISSSTS02' ELSE 'ISSSTS01' END AS ISS_STS , M5.CODE_NM AS ISS_STS_NM , W.ACT_ID , M.NAME AS ACT_NM , W.REQ_NO , W.FILE_TRGT_KEY , W.ISS_CNTS FROM salesCd S JOIN TB_WB24M02 W ON W.CO_CD = S.CO_CD AND W.SALES_CD = S.SALES_CD LEFT JOIN TB_CM06M01 M ON M.ID = W.ACT_ID LEFT JOIN TB_CM05M01 M5 ON M5.CODE_ID = W.ISS_STS LEFT JOIN TB_QM01M01 Q ON Q.REQ_NO = W.REQ_NO ) , req AS ( SELECT S.CO_CD , S.ORDRS_NO , S.ORDRS_CLNT_CD , S.ORDRS_CLNT_NM , S.CLNT_PJT , S.CLNT_PJT_NM , S.CTRT_NM , S.ISROOT , S.SALES_CD , S.EQP_NM , S.MCTYPE , S.MCTYPE_NM , S.ISS_SJ , S.ISS_NO , S.ISS_STS , S.ISS_STS_NM , S.ACT_ID , S.ACT_NM , S.REQ_NO , S.FILE_TRGT_KEY , Q.REG_ID , Q.REQ_ST , M.CODE_NM AS REQ_ST_NM , Q.REQ_RMK FROM iss S JOIN TB_QM01M01 Q ON Q.REQ_NO = S.REQ_NO LEFT JOIN TB_CM05M01 M ON M.CODE_ID = Q.REQ_ST ) -- 1. 최상위 '수주' 노드 (고정) SELECT 'ROOT_MASTER' AS ID , '' AS PARENTID , 'ROOT' AS ISROOT , '수주' AS TOPIC , '' AS FILE_TRGT_KEY , '' AS CO_CD , '' AS ORDRS_NO , '' AS ORDRS_CLNT_NM , '' AS CLNT_PJT_NM , '' AS SALES_CD , '' AS MCTYPE_NM , '' AS ISS_STS , '' AS ISS_STS_NM , '' AS ACT_ID , '' AS ACT_NM , '' AS REG_ID , '' AS REQ_ST , '' AS REQ_ST_NM , '' AS ISS_CNTS , '' AS REQ_RMK , '' AS VER_NO , '1' AS DATA_TYPE , 'right' AS DIRECTION FROM DUAL UNION ALL -- 2. 프로젝트 노드 ('수주'의 자식) SELECT ORDRS_NO AS ID , 'ROOT_MASTER' AS PARENTID , '' AS ISROOT , ORDRS_CLNT_NM || '_' || CLNT_PJT_NM AS TOPIC , '' AS FILE_TRGT_KEY , CO_CD AS CO_CD , ORDRS_NO , ORDRS_CLNT_NM , CLNT_PJT_NM , '' SALES_CD , '' MCTYPE_NM , '' ISS_STS , '' ISS_STS_NM , '' ACT_ID , '' ACT_NM , '' REG_ID , '' REQ_ST , '' REQ_ST_NM , '' ISS_CNTS , '' REQ_RMK , '' VER_NO , '2' AS DATA_TYPE , 'right' AS DIRECTION FROM root UNION ALL SELECT S.SALES_CD AS ID , S.ORDRS_NO AS PARENTID , S.ISROOT , S.EQP_NM AS TOPIC , '' AS FILE_TRGT_KEY , S.CO_CD , S.ORDRS_NO , S.ORDRS_CLNT_NM , S.CLNT_PJT_NM , S.SALES_CD , S.MCTYPE_NM , '' ISS_STS , '' ISS_STS_NM , '' ACT_ID , '' ACT_NM , '' REG_ID , '' REQ_ST , '' REQ_ST_NM , '' ISS_CNTS , '' REQ_RMK , W.VER_NO , '3' AS DATA_TYPE , 'right' AS DIRECTION FROM salesCd S LEFT JOIN wbs W ON W.CO_CD = S.CO_CD AND W.SALES_CD = S.SALES_CD UNION ALL SELECT ISS_NO AS ID , SALES_CD AS PARENTID , ISROOT , ISS_SJ AS TOPIC , FILE_TRGT_KEY , CO_CD , ORDRS_NO , ORDRS_CLNT_NM , CLNT_PJT_NM , SALES_CD , MCTYPE_NM , ISS_STS , ISS_STS_NM , ACT_ID , ACT_NM , '' REG_ID , '' REQ_ST , '' REQ_ST_NM , ISS_CNTS , '' REQ_RMK , '' VER_NO , '4' AS DATA_TYPE , 'right' AS DIRECTION FROM iss UNION ALL SELECT REQ_NO AS ID , ISS_NO AS PARENTID , ISROOT , REQ_NO AS TOPIC , FILE_TRGT_KEY , CO_CD , ORDRS_NO , ORDRS_CLNT_NM , CLNT_PJT_NM , SALES_CD , MCTYPE_NM , ISS_STS , ISS_STS_NM , ACT_ID , ACT_NM , REG_ID , REQ_ST , REQ_ST_NM , '' ISS_CNTS , REQ_RMK , '' VER_NO , '5' AS DATA_TYPE , 'right' AS DIRECTION FROM req

WITH act_agg AS ( SELECT ISS_NO , SUM(TO_NUMBER(NVL(ACT_MH, '0'))) AS ACT_MH , MAX(TO_NUMBER(NULLIF(SALE_TEAM_MD, ''))) AS SALE_TEAM_MD , MAX(TO_NUMBER(NULLIF(DSGN_TEAM_MD, ''))) AS DSGN_TEAM_MD , MAX(TO_NUMBER(NULLIF(MATR_TEAM_MD, ''))) AS MATR_TEAM_MD , MAX(TO_NUMBER(NULLIF(PROD_TEAM_MD, ''))) AS PROD_TEAM_MD FROM TB_WB24M03 GROUP BY ISS_NO ) , qp_agg AS ( SELECT REQ_NO , MAX(TO_NUMBER(NULLIF(SALE_TEAM_MD, ''))) AS SALE_TEAM_MD , MAX(TO_NUMBER(NULLIF(DSGN_TEAM_MD, ''))) AS DSGN_TEAM_MD , MAX(TO_NUMBER(NULLIF(MATR_TEAM_MD, ''))) AS MATR_TEAM_MD , MAX(TO_NUMBER(NULLIF(PROD_TEAM_MD, ''))) AS PROD_TEAM_MD FROM TB_QM01P01 GROUP BY REQ_NO ) , iss AS ( SELECT W.ISS_NO , W.ISS_SJ , W.ISS_STS , W.ACT_ID , W.REQ_NO , W.FILE_TRGT_KEY , W.ISS_CNTS , W.SALES_CD , W.CO_CD , W.SUB_CD , W.CREAT_DTTM , M.NAME AS ACT_NM , S.CODE_NM AS SUB_CD_NM , S.CODE_KIND AS GRP_CD , G.CODE_NM AS GRP_CD_NM , D.EQP_NM , D.MCTYPE , D.ORDRS_NO , M2.CODE_NM AS MCTYPE_NM , C.ORDRS_CLNT_CD , B.CLNT_NM AS ORDRS_CLNT_NM , C.CLNT_PJT , M3.CODE_NM AS CLNT_PJT_NM , Q.REQ_ST , Q.REQ_RMK , Q.REG_ID , M4.CODE_NM AS REQ_ST_NM , CASE WHEN ((W.ISS_STS = 'ISSSTS03') OR (Q.REQ_ST = 'REQST03')) THEN 'ISSSTS03' WHEN ((W.ISS_STS = 'ISSSTS02') OR (W.REQ_NO IS NOT NULL)) THEN 'ISSSTS02' ELSE 'ISSSTS01' END AS ISS_STS_CALC , NVL( CASE WHEN W.REQ_NO IS NOT NULL THEN (SELECT SUM(ME.PCHS_AMT) FROM TB_SM12D01 ME WHERE ME.REQ_NO = W.REQ_NO) ELSE (SELECT SUM(TO_NUMBER(NVL(A.ACT_AMT, '0'))) FROM TB_WB24M03 A WHERE A.ISS_NO = W.ISS_NO) END , 0) AS ISS_AMT , NVL(ACT.ACT_MH, 0) AS ACT_MH , NVL(ACT.SALE_TEAM_MD, NVL(QP.SALE_TEAM_MD, 0)) AS SALE_TEAM_MD , NVL(ACT.DSGN_TEAM_MD, NVL(QP.DSGN_TEAM_MD, 0)) AS DSGN_TEAM_MD , NVL(ACT.MATR_TEAM_MD, NVL(QP.MATR_TEAM_MD, 0)) AS MATR_TEAM_MD , NVL(ACT.PROD_TEAM_MD, NVL(QP.PROD_TEAM_MD, 0)) AS PROD_TEAM_MD , (COALESCE(ACT.SALE_TEAM_MD, QP.SALE_TEAM_MD, 0) + COALESCE(ACT.DSGN_TEAM_MD, QP.DSGN_TEAM_MD, 0) + COALESCE(ACT.MATR_TEAM_MD, QP.MATR_TEAM_MD, 0) + COALESCE(ACT.PROD_TEAM_MD, QP.PROD_TEAM_MD, 0)) AS SUM_TEAM_MD FROM TB_WB24M02 W LEFT JOIN TB_CM06M01 M ON M.ID = W.ACT_ID LEFT JOIN TB_CM05M01 S ON S.CODE_ID = W.SUB_CD LEFT JOIN TB_CM05M01 G ON G.CODE_ID = S.CODE_KIND LEFT JOIN TB_CR02D02 D ON D.CO_CD = W.CO_CD AND D.SALES_CD = W.SALES_CD LEFT JOIN TB_CM05M01 M2 ON M2.CODE_ID = D.MCTYPE LEFT JOIN TB_CR02M01 C ON C.CO_CD = D.CO_CD AND C.ORDRS_NO = D.ORDRS_NO LEFT JOIN TB_BM02M01 B ON B.CLNT_CD = C.ORDRS_CLNT_CD LEFT JOIN TB_CM05M01 M3 ON M3.CODE_ID = C.CLNT_PJT LEFT JOIN TB_QM01M01 Q ON Q.REQ_NO = W.REQ_NO LEFT JOIN TB_CM05M01 M4 ON M4.CODE_ID = Q.REQ_ST LEFT JOIN act_agg ACT ON ACT.ISS_NO = W.ISS_NO LEFT JOIN qp_agg QP ON QP.REQ_NO = W.REQ_NO WHERE W.ACT_ID = #{actId, jdbcType=VARCHAR}
AND W.CO_CD = #{coCd, jdbcType=VARCHAR}
AND W.CREAT_DTTM >= TO_DATE(#{fromDt, jdbcType=VARCHAR},'YYYY-MM-DD')
AND W.CREAT_DTTM < TO_DATE(#{toDt, jdbcType=VARCHAR},'YYYY-MM-DD') + 1
) SELECT 'ROOT_MASTER' AS ID , '' AS PARENTID , 'ROOT' AS ISROOT , (SELECT NVL(M.NAME, #{actId}) FROM TB_CM06M01 M WHERE M.ID = #{actId, jdbcType=VARCHAR}) AS TOPIC , '' AS FILE_TRGT_KEY , '' AS CO_CD , '' AS ORDRS_NO , '' AS ORDRS_CLNT_NM , '' AS CLNT_PJT_NM , '' AS SALES_CD , '' AS MCTYPE_NM , '' AS ISS_NO , '' AS REQ_NO , '' AS ISS_STS , '' AS ISS_STS_NM , '' AS ACT_ID , '' AS ACT_NM , '' AS SUB_CD , '' AS SUB_CD_NM , '' AS GRP_CD , '' AS GRP_CD_NM , '' AS REG_ID , '' AS REQ_ST , '' AS REQ_ST_NM , '' AS ISS_CNTS , '' AS REQ_RMK , 0 AS ISS_AMT , 0 AS ACT_MH , 0 AS SALE_TEAM_MD , 0 AS DSGN_TEAM_MD , 0 AS MATR_TEAM_MD , 0 AS PROD_TEAM_MD , 0 AS SUM_TEAM_MD , '1' AS DATA_TYPE , 'right' AS DIRECTION FROM DUAL UNION ALL SELECT DISTINCT 'G_' || NVL(GRP_CD,'NONE') AS ID , 'ROOT_MASTER' AS PARENTID , '' AS ISROOT , NVL(GRP_CD_NM,'미지정') AS TOPIC , '' AS FILE_TRGT_KEY , '' AS CO_CD , '' AS ORDRS_NO , '' AS ORDRS_CLNT_NM , '' AS CLNT_PJT_NM , '' AS SALES_CD , '' AS MCTYPE_NM , '' AS ISS_NO , '' AS REQ_NO , '' AS ISS_STS , '' AS ISS_STS_NM , '' AS ACT_ID , '' AS ACT_NM , '' AS SUB_CD , '' AS SUB_CD_NM , GRP_CD , GRP_CD_NM , '' AS REG_ID , '' AS REQ_ST , '' AS REQ_ST_NM , '' AS ISS_CNTS , '' AS REQ_RMK , 0 AS ISS_AMT , 0 AS ACT_MH , 0 AS SALE_TEAM_MD , 0 AS DSGN_TEAM_MD , 0 AS MATR_TEAM_MD , 0 AS PROD_TEAM_MD , 0 AS SUM_TEAM_MD , '7' AS DATA_TYPE , 'right' AS DIRECTION FROM iss UNION ALL SELECT DISTINCT 'T_' || NVL(SUB_CD,'NONE') AS ID , 'G_' || NVL(GRP_CD,'NONE') AS PARENTID , '' AS ISROOT , NVL(SUB_CD_NM,'미지정') AS TOPIC , '' AS FILE_TRGT_KEY , '' AS CO_CD , '' AS ORDRS_NO , '' AS ORDRS_CLNT_NM , '' AS CLNT_PJT_NM , '' AS SALES_CD , '' AS MCTYPE_NM , '' AS ISS_NO , '' AS REQ_NO , '' AS ISS_STS , '' AS ISS_STS_NM , '' AS ACT_ID , '' AS ACT_NM , SUB_CD , SUB_CD_NM , GRP_CD , GRP_CD_NM , '' AS REG_ID , '' AS REQ_ST , '' AS REQ_ST_NM , '' AS ISS_CNTS , '' AS REQ_RMK , 0 AS ISS_AMT , 0 AS ACT_MH , 0 AS SALE_TEAM_MD , 0 AS DSGN_TEAM_MD , 0 AS MATR_TEAM_MD , 0 AS PROD_TEAM_MD , 0 AS SUM_TEAM_MD , '8' AS DATA_TYPE , 'right' AS DIRECTION FROM iss UNION ALL SELECT ISS_NO || 'T' AS ID , 'T_' || NVL(SUB_CD,'NONE') AS PARENTID , '' AS ISROOT , ISS_SJ AS TOPIC , FILE_TRGT_KEY , CO_CD , ORDRS_NO , ORDRS_CLNT_NM , CLNT_PJT_NM , SALES_CD , MCTYPE_NM , ISS_NO , REQ_NO , ISS_STS_CALC AS ISS_STS , CASE WHEN ISS_STS_CALC='ISSSTS03' THEN (SELECT CODE_NM FROM TB_CM05M01 WHERE CODE_ID = 'ISSSTS03') WHEN ISS_STS_CALC='ISSSTS02' THEN (SELECT CODE_NM FROM TB_CM05M01 WHERE CODE_ID = 'ISSSTS02') ELSE (SELECT CODE_NM FROM TB_CM05M01 WHERE CODE_ID = 'ISSSTS01') END AS ISS_STS_NM , ACT_ID , ACT_NM , SUB_CD , SUB_CD_NM , GRP_CD , GRP_CD_NM , '' AS REG_ID , '' AS REQ_ST , '' AS REQ_ST_NM , ISS_CNTS , '' AS REQ_RMK , ISS_AMT , ACT_MH , SALE_TEAM_MD , DSGN_TEAM_MD , MATR_TEAM_MD , PROD_TEAM_MD , SUM_TEAM_MD , '4' AS DATA_TYPE , 'right' AS DIRECTION FROM iss UNION ALL SELECT REQ_NO || 'T' AS ID , ISS_NO || 'T' AS PARENTID , '' AS ISROOT , REQ_NO AS TOPIC , FILE_TRGT_KEY , CO_CD , ORDRS_NO , ORDRS_CLNT_NM , CLNT_PJT_NM , SALES_CD , MCTYPE_NM , ISS_NO , REQ_NO , ISS_STS_CALC AS ISS_STS , CASE WHEN ISS_STS_CALC='ISSSTS03' THEN (SELECT CODE_NM FROM TB_CM05M01 WHERE CODE_ID = 'ISSSTS03') WHEN ISS_STS_CALC='ISSSTS02' THEN (SELECT CODE_NM FROM TB_CM05M01 WHERE CODE_ID = 'ISSSTS02') ELSE (SELECT CODE_NM FROM TB_CM05M01 WHERE CODE_ID = 'ISSSTS01') END AS ISS_STS_NM , ACT_ID , ACT_NM , SUB_CD , SUB_CD_NM , GRP_CD , GRP_CD_NM , REG_ID , REQ_ST , REQ_ST_NM , '' AS ISS_CNTS , REQ_RMK , ISS_AMT , ACT_MH , SALE_TEAM_MD , DSGN_TEAM_MD , MATR_TEAM_MD , PROD_TEAM_MD , SUM_TEAM_MD , '5' AS DATA_TYPE , 'right' AS DIRECTION FROM iss WHERE REQ_NO IS NOT NULL UNION ALL SELECT DISTINCT NVL(ORDRS_NO,'NONE') || 'E' AS ID , 'ROOT_MASTER' AS PARENTID , '' AS ISROOT , CASE WHEN ORDRS_CLNT_NM IS NULL AND CLNT_PJT_NM IS NULL THEN '미지정' ELSE NVL(ORDRS_CLNT_NM,'') || '_' || NVL(CLNT_PJT_NM,'') END AS TOPIC , '' AS FILE_TRGT_KEY , CO_CD , ORDRS_NO , ORDRS_CLNT_NM , CLNT_PJT_NM , '' AS SALES_CD , '' AS MCTYPE_NM , '' AS ISS_NO , '' AS REQ_NO , '' AS ISS_STS , '' AS ISS_STS_NM , '' AS ACT_ID , '' AS ACT_NM , '' AS SUB_CD , '' AS SUB_CD_NM , '' AS GRP_CD , '' AS GRP_CD_NM , '' AS REG_ID , '' AS REQ_ST , '' AS REQ_ST_NM , '' AS ISS_CNTS , '' AS REQ_RMK , 0 AS ISS_AMT , 0 AS ACT_MH , 0 AS SALE_TEAM_MD , 0 AS DSGN_TEAM_MD , 0 AS MATR_TEAM_MD , 0 AS PROD_TEAM_MD , 0 AS SUM_TEAM_MD , '2' AS DATA_TYPE , 'left' AS DIRECTION FROM iss UNION ALL SELECT DISTINCT NVL(SALES_CD,'NONE') || 'E' AS ID , NVL(ORDRS_NO,'NONE') || 'E' AS PARENTID , '' AS ISROOT , COALESCE(EQP_NM, SALES_CD, '미지정') AS TOPIC , '' AS FILE_TRGT_KEY , CO_CD , ORDRS_NO , ORDRS_CLNT_NM , CLNT_PJT_NM , SALES_CD , MCTYPE_NM , '' AS ISS_NO , '' AS REQ_NO , '' AS ISS_STS , '' AS ISS_STS_NM , '' AS ACT_ID , '' AS ACT_NM , '' AS SUB_CD , '' AS SUB_CD_NM , '' AS GRP_CD , '' AS GRP_CD_NM , '' AS REG_ID , '' AS REQ_ST , '' AS REQ_ST_NM , '' AS ISS_CNTS , '' AS REQ_RMK , 0 AS ISS_AMT , 0 AS ACT_MH , 0 AS SALE_TEAM_MD , 0 AS DSGN_TEAM_MD , 0 AS MATR_TEAM_MD , 0 AS PROD_TEAM_MD , 0 AS SUM_TEAM_MD , '3' AS DATA_TYPE , 'left' AS DIRECTION FROM iss UNION ALL SELECT ISS_NO || 'E' AS ID , NVL(SALES_CD,'NONE') || 'E' AS PARENTID , '' AS ISROOT , ISS_SJ AS TOPIC , FILE_TRGT_KEY , CO_CD , ORDRS_NO , ORDRS_CLNT_NM , CLNT_PJT_NM , SALES_CD , MCTYPE_NM , ISS_NO , REQ_NO , ISS_STS_CALC AS ISS_STS , CASE WHEN ISS_STS_CALC='ISSSTS03' THEN (SELECT CODE_NM FROM TB_CM05M01 WHERE CODE_ID = 'ISSSTS03') WHEN ISS_STS_CALC='ISSSTS02' THEN (SELECT CODE_NM FROM TB_CM05M01 WHERE CODE_ID = 'ISSSTS02') ELSE (SELECT CODE_NM FROM TB_CM05M01 WHERE CODE_ID = 'ISSSTS01') END AS ISS_STS_NM , ACT_ID , ACT_NM , SUB_CD , SUB_CD_NM , GRP_CD , GRP_CD_NM , '' AS REG_ID , '' AS REQ_ST , '' AS REQ_ST_NM , ISS_CNTS , '' AS REQ_RMK , ISS_AMT , ACT_MH , SALE_TEAM_MD , DSGN_TEAM_MD , MATR_TEAM_MD , PROD_TEAM_MD , SUM_TEAM_MD , '4' AS DATA_TYPE , 'left' AS DIRECTION FROM iss UNION ALL SELECT REQ_NO || 'E' AS ID , ISS_NO || 'E' AS PARENTID , '' AS ISROOT , REQ_NO AS TOPIC , FILE_TRGT_KEY , CO_CD , ORDRS_NO , ORDRS_CLNT_NM , CLNT_PJT_NM , SALES_CD , MCTYPE_NM , ISS_NO , REQ_NO , ISS_STS_CALC AS ISS_STS , CASE WHEN ISS_STS_CALC='ISSSTS03' THEN (SELECT CODE_NM FROM TB_CM05M01 WHERE CODE_ID = 'ISSSTS03') WHEN ISS_STS_CALC='ISSSTS02' THEN (SELECT CODE_NM FROM TB_CM05M01 WHERE CODE_ID = 'ISSSTS02') ELSE (SELECT CODE_NM FROM TB_CM05M01 WHERE CODE_ID = 'ISSSTS01') END AS ISS_STS_NM , ACT_ID , ACT_NM , SUB_CD , SUB_CD_NM , GRP_CD , GRP_CD_NM , REG_ID , REQ_ST , REQ_ST_NM , '' AS ISS_CNTS , REQ_RMK , ISS_AMT , ACT_MH , SALE_TEAM_MD , DSGN_TEAM_MD , MATR_TEAM_MD , PROD_TEAM_MD , SUM_TEAM_MD , '5' AS DATA_TYPE , 'left' AS DIRECTION FROM iss WHERE REQ_NO IS NOT NULL

WITH agenda AS ( SELECT M.FILE_TRGT_KEY , M.CO_CD , M.MNG_ID , M.CLNT_CD , B.CLNT_NM AS ORDRS_CLNT_NM , M.CLNT_PJT , E.CODE_NM AS CLNT_PJT_NM , M.ORDRS_NO , M.SALES_CD , M.CREAT_ID , D.AGENDA_NO , D.AGENDA_TITLE , D3.AGENDA_CNTS , D.AGENDA_STATUS , D.CREAT_DTTM AS AGENDA_CREAT_DTTM , '' MCTYPE_NM , '' AS ISROOT FROM TB_PM20M01 M LEFT JOIN TB_PM20D01 D ON D.FILE_TRGT_KEY = M.FILE_TRGT_KEY LEFT JOIN TB_PM20D03 D3 ON D3.FILE_TRGT_KEY = M.FILE_TRGT_KEY AND D3.AGENDA_NO = D.AGENDA_NO AND D3.AGENDA_VER = (SELECT MAX(AGENDA_VER) FROM TB_PM20D03 D3 WHERE D3.FILE_TRGT_KEY = M.FILE_TRGT_KEY AND D3.AGENDA_NO = D.AGENDA_NO) LEFT JOIN TB_CM05M01 E ON E.CODE_ID = M.CLNT_PJT LEFT JOIN TB_BM02M01 B ON B.CLNT_CD = M.CLNT_CD WHERE M.BIZ_DIV = 'AGENDA01'
AND M.SALES_CD LIKE '%' || #{salesCd} || '%'
) , root AS ( SELECT DISTINCT A.CO_CD , A.ORDRS_NO , C.ORDRS_CLNT_CD , B.CLNT_NM AS ORDRS_CLNT_NM , C.CLNT_PJT , M.CODE_NM AS CLNT_PJT_NM , C.CTRT_NM , 'ROOT' AS ISROOT FROM agenda A LEFT JOIN TB_CR02M01 C ON C.ORDRS_NO = A.ORDRS_NO LEFT JOIN TB_CM05M01 M ON M.CODE_ID = C.CLNT_PJT LEFT JOIN TB_BM02M01 B ON B.CLNT_CD = C.ORDRS_CLNT_CD WHERE 1=1
AND A.ORDRS_NO LIKE '%' || #{ordrsNo} || '%'
) , salesCd AS ( SELECT DISTINCT C.CO_CD , C.ORDRS_NO , C.ORDRS_CLNT_CD , C.ORDRS_CLNT_NM , C.CLNT_PJT , C.CLNT_PJT_NM , C.CTRT_NM , '' AS ISROOT , D.SALES_CD , D.EQP_NM , D.MCTYPE , M.CODE_NM AS MCTYPE_NM , D.ORDRS_SEQ FROM root C JOIN agenda A ON A.CO_CD = C.CO_CD AND A.ORDRS_NO = C.ORDRS_NO JOIN TB_CR02D02 D ON D.CO_CD = C.CO_CD AND D.ORDRS_NO = C.ORDRS_NO AND D.SALES_CD = A.SALES_CD LEFT JOIN TB_CM05M01 M ON M.CODE_ID = D.MCTYPE WHERE D.SALES_CD IS NOT NULL ) SELECT ORDRS_NO || 'A' AS ID , 'ROOT_MASTER' AS PARENTID , '' ISROOT , ORDRS_CLNT_NM || '_' || CLNT_PJT_NM AS TOPIC , '' FILE_TRGT_KEY , CO_CD , ORDRS_NO , ORDRS_CLNT_NM , CLNT_PJT_NM , '' SALES_CD , '' MCTYPE_NM , '' AGENDA_STATUS , '' AGENDA_STATUS_NM , '' ACT_ID , '' ACT_NM , '' REG_ID , '' REQ_ST , '' REQ_ST_NM , '' AGENDA_CNTS , '2' AS DATA_TYPE , 'left' AS DIRECTION FROM root UNION ALL SELECT SALES_CD || 'A' AS ID , ORDRS_NO || 'A' AS PARENTID , ISROOT , EQP_NM AS TOPIC , '' FILE_TRGT_KEY , CO_CD , ORDRS_NO , ORDRS_CLNT_NM , CLNT_PJT_NM , SALES_CD , MCTYPE_NM , '' AGENDA_STATUS , '' AGENDA_STATUS_NM , '' ACT_ID , '' ACT_NM , '' REG_ID , '' REQ_ST , '' REQ_ST_NM , '' AGENDA_CNTS , '3' AS DATA_TYPE , 'left' AS DIRECTION FROM salesCd UNION ALL SELECT FILE_TRGT_KEY || '-' || AGENDA_NO AS ID , SALES_CD || 'A' AS PARENTID , ISROOT , AGENDA_TITLE AS TOPIC , FILE_TRGT_KEY , CO_CD , ORDRS_NO , ORDRS_CLNT_NM , CLNT_PJT_NM , SALES_CD , MCTYPE_NM , AGENDA_STATUS , case WHEN AGENDA_STATUS='Y' THEN '완료' ELSE '진행중' END AGENDA_STATUS_NM , '' ACT_ID , '' ACT_NM , '' REG_ID , '' REQ_ST , '' REQ_ST_NM , AGENDA_CNTS , '6' AS DATA_TYPE , 'left' AS DIRECTION FROM agenda
